    @Test
    /**
     * Full Create-Read-Update-Delete of a Routing, through a RoutingTest.
     */
    public void testCRUD() throws Throwable {
    try {
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "Beginning full test on RoutingTest..." );

        testCreate();
        testRead();
        testUpdate();
        testGetAll();
        testDelete();

        LOGGER.info( "Successfully ran a full test on RoutingTest..." );
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "" );
    }
    catch( Throwable e ) {
        throw e;
    }
    finally  {
        if ( handler != null ) {
            handler.flush();
            LOGGER.removeHandler(handler);
        }
    }
}

    /**
     * Tests creating a new Routing.
     *
     * @return    Routing
     */
    public Routing testCreate() throws Throwable {
    Routing entity = null;

    LOGGER.info( "RoutingTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Routing");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Routing" );

    try {
        entity = service.createRouting( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getRoutingId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Routing with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a Routing.
     *
     * @return    Routing
     */
    public Routing testRead() throws Throwable {
    LOGGER.info( "RoutingTest:testRead()" );
    LOGGER.info( "-- Reading a previously created Routing" );

    Routing entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read Routing with primary key" );
    msg.append( theId );

    try {
        entity = service.getRouting( new RoutingFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getRoutingId();

        LOGGER.info( "-- Successfully found Routing " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a Routing.
     *
     * @return    Routing
     */
    public Routing testUpdate() throws Throwable {
    LOGGER.info( "RoutingTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Routing." );

    StringBuilder msg = new StringBuilder( "Failed to update a Routing : " );
    Routing entity = null;

    try {
        UpdateRoutingCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setRoutingId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Routing." );

        entity = service.updateRouting( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Routing - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a Routing.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "RoutingTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created Routing." );

    try {
        DeleteRoutingCommand deleteCommand = new DeleteRoutingCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted Routing with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete Routing with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all Routings.
     *
     * @return    Collection
     */
    public List<Routing> testGetAll() throws Throwable {
    LOGGER.info( "RoutingTest:testGetAll() - Retrieving Collection of Routings:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Routing : " );
    List<Routing> collection  = null;

    try {
        // call the static get method on the RoutingService
        collection = service.getAllRouting();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Routing currEntity  = null;
            Iterator<Routing> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getRoutingId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

    public RoutingTest setHandler( Handler handler ) {
    this.handler = handler;
    LOGGER.addHandler(handler);	// assign so the LOGGER can only output results to the Handler
    return this;
}


